def solve(jobs, quantum):
    from collections import deque
    pending, elapsed, result = deque((name,time) for name,time in jobs), 0, []
    while pending:
        name, remaining = pending.popleft()
        used = min(quantum,remaining)
        elapsed += used; remaining -= used
        if remaining: pending.append((name,remaining))
        else: result.append([name,elapsed])
    return result
